#include <stdio.h>
#include <string.h>

/* 单步转换：合法则返回目标状态名，非法返回 NULL */
static const char *transit(const char *state, const char *ev) {
    if (!strcmp(state, "创建") && !strcmp(ev, "admit"))    return "就绪";
    if (!strcmp(state, "就绪") && !strcmp(ev, "dispatch")) return "运行";
    if (!strcmp(state, "运行") && !strcmp(ev, "timeout"))  return "就绪";
    if (!strcmp(state, "运行") && !strcmp(ev, "wait"))     return "阻塞";
    if (!strcmp(state, "阻塞") && !strcmp(ev, "wakeup"))   return "就绪";
    if (!strcmp(state, "运行") && !strcmp(ev, "exit"))     return "终止";
    return NULL; /* 非法转换 */
}

/* events: 事件数组；n: 事件个数。返回最终状态名或 "ERR" */
const char *solve(const char *events[], int n) {
    const char *state = "创建";
    for (int i = 0; i < n; ++i) {
        const char *nxt = transit(state, events[i]);
        if (nxt == NULL) return "ERR";
        state = nxt;
    }
    return state;
}
